CREATE OR REPLACE FUNCTION hr_public.create_review_with_goals(p_employee_id uuid, p_reviewer_id uuid, p_review_type hr_public.review_type, p_review_period_start date DEFAULT NULL::date, p_review_period_end date DEFAULT NULL::date, p_goal_ids uuid[] DEFAULT '{}'::uuid[], p_new_goals jsonb DEFAULT '[]'::jsonb, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_review_id UUID;
  v_current_user_role TEXT;
  v_is_direct_manager BOOLEAN;
  v_duplicate_count INT;
  v_new_goal_id UUID;
  v_new_goal JSONB;
  v_result JSONB;
  v_review_period TEXT;
BEGIN
  -- Get reviewer user role
  SELECT role INTO v_current_user_role
  FROM hr_public.users
  WHERE id = p_reviewer_id;

  -- Validate reviewer exists
  IF v_current_user_role IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Reviewer not found',
      'review', NULL
    );
  END IF;

  -- RBAC: Check if manager is trying to create review for non-direct report
  IF v_current_user_role IN ('manager', 'hr_manager') THEN
    v_is_direct_manager := hr_public.is_direct_manager(p_employee_id, p_reviewer_id);

    IF NOT v_is_direct_manager THEN
      RETURN jsonb_build_object(
        'success', false,
        'message', 'You can only create reviews for your direct reports',
        'review', NULL
      );
    END IF;
  END IF;

  -- Check for duplicate active reviews of same type
  SELECT COUNT(*) INTO v_duplicate_count
  FROM hr_public.performance_reviews
  WHERE employee_id = p_employee_id
    AND review_type = p_review_type
    AND status IN ('draft', 'in_progress');

  IF v_duplicate_count > 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Active ' || p_review_type || ' already exists for this employee',
      'review', NULL
    );
  END IF;

  -- Generate review_period string
  IF p_review_period_start IS NOT NULL THEN
    -- Use year from start date
    v_review_period := EXTRACT(YEAR FROM p_review_period_start)::TEXT || ' - ' ||
                       REPLACE(INITCAP(REPLACE(p_review_type::TEXT, '_', ' ')), 'Review', 'Review');
  ELSE
    -- Use current year and review type
    v_review_period := EXTRACT(YEAR FROM CURRENT_DATE)::TEXT || ' - ' ||
                       REPLACE(INITCAP(REPLACE(p_review_type::TEXT, '_', ' ')), 'Review', 'Review');
  END IF;

  -- Create performance review
  INSERT INTO hr_public.performance_reviews (
    employee_id,
    reviewer_id,
    review_period,
    review_type,
    status,
    review_period_start,
    review_period_end,
    notes
  ) VALUES (
    p_employee_id,
    p_reviewer_id,
    v_review_period,
    p_review_type,
    'draft',
    p_review_period_start,
    p_review_period_end,
    p_notes
  ) RETURNING id INTO v_review_id;

  -- Create new goals if provided
  IF jsonb_array_length(p_new_goals) > 0 THEN
    FOR v_new_goal IN SELECT * FROM jsonb_array_elements(p_new_goals)
    LOOP
      INSERT INTO hr_public.employee_goals (
        employee_id,
        title,
        description,
        target_date,
        status,
        created_by
      ) VALUES (
        p_employee_id,
        v_new_goal->>'title',
        v_new_goal->>'description',
        (v_new_goal->>'targetCompletionDate')::DATE,
        'in_progress',
        p_reviewer_id
      ) RETURNING id INTO v_new_goal_id;

      -- Link new goal to review
      INSERT INTO hr_public.review_goals (review_id, goal_id)
      VALUES (v_review_id, v_new_goal_id);
    END LOOP;
  END IF;

  -- Link existing goals to review
  IF array_length(p_goal_ids, 1) > 0 THEN
    INSERT INTO hr_public.review_goals (review_id, goal_id)
    SELECT v_review_id, unnest(p_goal_ids);
  END IF;

  -- Return success response with review data
  SELECT jsonb_build_object(
    'success', true,
    'message', 'Review created successfully',
    'review', row_to_json(pr.*)
  ) INTO v_result
  FROM hr_public.performance_reviews pr
  WHERE pr.id = v_review_id;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.decrypt_key_data(p_encrypted_key_data bytea, p_key_identifier character varying)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    encryption_password TEXT;
BEGIN
    encryption_password := p_key_identifier || '_SERVER_SECRET_KEY_PLACEHOLDER';

    -- Decrypt using pgcrypto
    RETURN pgp_sym_decrypt_bytea(p_encrypted_key_data, encryption_password);
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.execute_rollback(p_log_id uuid, p_reason text, p_strategy text DEFAULT 'force'::text, p_executed_by uuid DEFAULT NULL::uuid)
 RETURNS TABLE(success boolean, new_log_id uuid, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_target_log hr_public.activity_logs%ROWTYPE;
    v_resource_table TEXT;
    v_resource_id UUID;
    v_before_snapshot JSONB;
    v_after_snapshot JSONB;
    v_new_log_id UUID;
    v_current_user_id UUID;
BEGIN
    -- Get current user ID if not provided
    v_current_user_id := COALESCE(
        p_executed_by,
        NULLIF(current_setting('jwt.claims.user_id', true), '')::UUID
    );

    -- Validate user permissions (must be super_admin)
    IF current_setting('jwt.claims.role', true) != 'super_admin' THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Only super_admin can execute rollbacks'::TEXT;
        RETURN;
    END IF;

    -- Validate reason
    IF p_reason IS NULL OR LENGTH(TRIM(p_reason)) < 10 THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Rollback reason must be at least 10 characters'::TEXT;
        RETURN;
    END IF;

    -- Get the target activity log
    SELECT * INTO v_target_log
    FROM hr_public.activity_logs
    WHERE id = p_log_id;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Activity log not found'::TEXT;
        RETURN;
    END IF;

    -- Validate: Cannot rollback a rollback
    IF v_target_log.is_rollback = TRUE THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Cannot rollback a rollback operation'::TEXT;
        RETURN;
    END IF;

    -- Validate: Cannot rollback VIEW operations
    IF UPPER(v_target_log.action) = 'VIEW' THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Cannot rollback view operations'::TEXT;
        RETURN;
    END IF;

    -- Check if already rolled back
    IF EXISTS (
        SELECT 1 FROM hr_public.activity_logs
        WHERE rolled_back_log_id = p_log_id
    ) THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'This operation has already been rolled back'::TEXT;
        RETURN;
    END IF;

    -- Get resource information
    v_resource_id := v_target_log.resource_id;
    v_before_snapshot := v_target_log.before_snapshot;
    v_after_snapshot := v_target_log.after_snapshot;

    -- Determine the target table based on resource_type (just table name, we'll use hr_public schema)
    v_resource_table := CASE v_target_log.resource_type
        WHEN 'events' THEN 'events'
        WHEN 'event' THEN 'events'
        WHEN 'tasks' THEN 'tasks'
        WHEN 'task' THEN 'tasks'
        WHEN 'leave_requests' THEN 'leave_requests'
        WHEN 'leave_request' THEN 'leave_requests'
        WHEN 'users' THEN 'users'
        WHEN 'profile' THEN 'users'
        WHEN 'employee' THEN 'users'
        WHEN 'departments' THEN 'departments'
        WHEN 'department' THEN 'departments'
        ELSE NULL
    END;

    IF v_resource_table IS NULL THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, format('Unsupported resource type: %s', v_target_log.resource_type)::TEXT;
        RETURN;
    END IF;

    -- Execute the rollback based on the original action
    BEGIN
        IF UPPER(v_target_log.action) = 'CREATE' THEN
            -- Rollback CREATE = DELETE the resource
            EXECUTE format('DELETE FROM hr_public.%I WHERE id = $1', v_resource_table)
            USING v_resource_id;

            -- Create rollback activity log
            INSERT INTO hr_public.activity_logs (
                employee_id,
                user_id,
                action,
                resource_type,
                resource_id,
                before_snapshot,
                after_snapshot,
                is_rollback,
                rolled_back_log_id,
                details,
                ip_address,
                user_agent
            ) VALUES (
                v_current_user_id,
                v_current_user_id,
                'delete',
                v_target_log.resource_type,
                v_resource_id,
                v_after_snapshot, -- What it was before rollback
                NULL, -- Now it's deleted
                TRUE,
                p_log_id,
                jsonb_build_object(
                    'rollback_reason', p_reason,
                    'rollback_strategy', p_strategy,
                    'original_action', 'create'
                ),
                NULL,
                NULL
            ) RETURNING id INTO v_new_log_id;

        ELSIF UPPER(v_target_log.action) = 'DELETE' THEN
            -- Rollback DELETE = Re-CREATE the resource
            -- This is complex as we need to restore all fields
            EXECUTE format(
                'INSERT INTO hr_public.%I SELECT * FROM jsonb_populate_record(NULL::hr_public.%I, $1)',
                v_resource_table,
                v_resource_table
            ) USING v_before_snapshot;

            -- Create rollback activity log
            INSERT INTO hr_public.activity_logs (
                employee_id,
                user_id,
                action,
                resource_type,
                resource_id,
                before_snapshot,
                after_snapshot,
                is_rollback,
                rolled_back_log_id,
                details,
                ip_address,
                user_agent
            ) VALUES (
                v_current_user_id,
                v_current_user_id,
                'create',
                v_target_log.resource_type,
                v_resource_id,
                NULL,
                v_before_snapshot,
                TRUE,
                p_log_id,
                jsonb_build_object(
                    'rollback_reason', p_reason,
                    'rollback_strategy', p_strategy,
                    'original_action', 'delete'
                ),
                NULL,
                NULL
            ) RETURNING id INTO v_new_log_id;

        ELSIF UPPER(v_target_log.action) = 'UPDATE' THEN
            -- Rollback UPDATE = UPDATE to before_snapshot
            -- Build dynamic UPDATE statement
            DECLARE
                v_update_sql TEXT;
                v_set_clauses TEXT[];
                v_key TEXT;
                v_value TEXT;
            BEGIN
                -- Build SET clauses from before_snapshot
                FOR v_key, v_value IN SELECT * FROM jsonb_each_text(v_before_snapshot)
                LOOP
                    IF v_key != 'id' THEN -- Don't update the ID
                        v_set_clauses := array_append(
                            v_set_clauses,
                            format('%I = %L', v_key, v_value)
                        );
                    END IF;
                END LOOP;

                IF array_length(v_set_clauses, 1) > 0 THEN
                    v_update_sql := format(
                        'UPDATE hr_public.%I SET %s WHERE id = $1',
                        v_resource_table,
                        array_to_string(v_set_clauses, ', ')
                    );

                    EXECUTE v_update_sql USING v_resource_id;
                END IF;
            END;

            -- Create rollback activity log
            INSERT INTO hr_public.activity_logs (
                employee_id,
                user_id,
                action,
                resource_type,
                resource_id,
                before_snapshot,
                after_snapshot,
                is_rollback,
                rolled_back_log_id,
                details,
                ip_address,
                user_agent
            ) VALUES (
                v_current_user_id,
                v_current_user_id,
                'update',
                v_target_log.resource_type,
                v_resource_id,
                v_after_snapshot, -- Current state before rollback
                v_before_snapshot, -- Restored state
                TRUE,
                p_log_id,
                jsonb_build_object(
                    'rollback_reason', p_reason,
                    'rollback_strategy', p_strategy,
                    'original_action', 'update'
                ),
                NULL,
                NULL
            ) RETURNING id INTO v_new_log_id;

        ELSE
            RETURN QUERY SELECT FALSE, NULL::UUID, format('Unsupported action type: %s', v_target_log.action)::TEXT;
            RETURN;
        END IF;

        -- Success
        RETURN QUERY SELECT TRUE, v_new_log_id, NULL::TEXT;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN QUERY SELECT FALSE, NULL::UUID, format('Rollback failed: %s', SQLERRM)::TEXT;
    END;
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.prevent_circular_dependencies()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  has_cycle BOOLEAN;
BEGIN
  WITH RECURSIVE dep_chain AS (
    SELECT NEW.blocking_task_id AS task_id, NEW.blocked_task_id AS depends_on
    UNION
    SELECT dc.task_id, td.blocked_task_id
    FROM dep_chain dc
    JOIN hr_public.task_dependencies td ON dc.depends_on = td.blocking_task_id
  )
  SELECT EXISTS(
    SELECT 1 FROM dep_chain
    WHERE task_id = depends_on
  ) INTO has_cycle;

  IF has_cycle THEN
    RAISE EXCEPTION 'Circular dependency detected';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.update_attendance_records_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.update_review_status(p_id uuid, p_status hr_public.review_status)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  UPDATE hr_public.performance_reviews
  SET
    status = p_status,
    updated_at = CURRENT_TIMESTAMP
  WHERE id = p_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Review not found',
      'review', NULL
    );
  END IF;

  SELECT jsonb_build_object(
    'success', true,
    'message', 'Review status updated successfully',
    'review', row_to_json(pr.*)
  ) INTO v_result
  FROM hr_public.performance_reviews pr
  WHERE pr.id = p_id;

  RETURN v_result;
END;
$function$
